<div class="mx-auto max-w-4xl"><div class="mb-8"><h1 class="text-2xl font-bold">Report settings</h1><p class="text-slate-500">Controls result calculations and exactly what appears on printed term reports.</p></div>@if(session('status'))<div class="mb-4 rounded-xl bg-emerald-50 p-3 text-emerald-700">{{session('status')}}</div>@endif<form wire:submit="save" class="rounded-2xl border bg-white p-6"><div class="grid gap-5 md:grid-cols-2"><label>School report level<select wire:model.live="level" class="mt-1 w-full rounded-xl border-slate-200"><option value="primary">Primary</option><option value="secondary">Secondary</option></select><small>Primary uses all subjects; Secondary can use best subjects and aggregates.</small></label><label>Pass mark<input wire:model="passMark" type="number" min="0" max="100" class="mt-1 w-full rounded-xl border-slate-200"><small>Average required for a pass recommendation.</small></label>@if($level==='secondary')<label>Best subjects for aggregate<input wire:model="bestSubjects" type="number" min="1" class="mt-1 w-full rounded-xl border-slate-200"></label>@endif<label>Show class position<select wire:model="showPosition" class="mt-1 w-full rounded-xl border-slate-200"><option value="enabled">Show</option><option value="disabled">Hide</option></select></label><label>Show attendance<select wire:model="showAttendance" class="mt-1 w-full rounded-xl border-slate-200"><option value="enabled">Show</option><option value="disabled">Hide</option></select></label><label>Show finance summary<select wire:model="showFees" class="mt-1 w-full rounded-xl border-slate-200"><option value="enabled">Show</option><option value="disabled">Hide</option></select></label><label>Show promotion decision<select wire:model="showPromotion" class="mt-1 w-full rounded-xl border-slate-200"><option value="disabled">Hide for this report</option><option value="enabled">Show</option></select><small>Keep hidden while Term 1 reports are issued.</small></label><label class="md:col-span-2">Report footer<textarea wire:model="footer" class="mt-1 w-full rounded-xl border-slate-200" rows="3" placeholder="School values, next-term opening date, or report note"></textarea></label></div><button class="mt-6 rounded-xl bg-yellow-400 px-6 py-3 font-bold">Save report settings</button></form></div>
